    CNOP    0,2

ComputeX:
    move.l  d1,-(sp)
    move.w  FontX,d1
    bra.s   ComputeItX
ComputeY:
    move.l  d1,-(sp)
    move.w  FontY,d1
    mulu    d1,d0
    addq.w  #4,d0
    divu    #8,d0
    move.l  (sp)+,d1
    rts

ComputeItX:
    mulu    d1,d0
    addq.w  #4,d0
    divu    #8,d0
    move.l  (sp)+,d1
    rts

ComputeFont:
    lea.l   Attr,a0
    move.l  a0,Font
    move.l  Scr,a1
    lea.l   sc_RastPort(a1),a1
    move.l  rp_Font(a1),a1
    move.l  LN_NAME(a1),ta_Name(a0)
    move.w  tf_YSize(a1),ta_YSize(a0)
    move.w  tf_XSize(a1),FontX
    move.w  tf_YSize(a1),FontY
    move.l  Scr,a0
    move.b  sc_WBorLeft(a0),d0
    ext.w   d0
    move.w  d0,OffX
    move.l  sc_Font(a0),a1
    move.w  ta_YSize(a1),d0
    addq.w  #1,d0
    move.b  sc_WBorTop(a0),d1
    ext.w   d1
    add.w   d1,d0
    move.w  d0,OffY
    tst.w   d2
    beq.s   CompDone
    tst.w   d3
    beq.s   CompDone
    move.w  d2,d0
    jsr     ComputeX
    add.w   OffX,d0
    move.b  sc_WBorRight(a0),d1
    ext.w   d1
    add.w   d1,d0
    cmp.w   sc_Width(a0),d0
    bhi.s   UseTopaz
    move.w  d3,d0
    jsr     ComputeY
    add.w   OffY,d0
    move.b  sc_WBorBottom(a0),d1
    ext.w   d1
    add.w   d1,d0
    cmp.w   sc_Height(a0),d0
    bhi.s   UseTopaz
CompDone:
    rts
UseTopaz:
    move.l  Font,a0
    move.l  #TopazName,ta_Name(a0)
    move.w  #8,FontY
    move.w  #8,FontX
    move.w  #8,ta_YSize(a0)
    rts

    XDEF    SetupScreen

SetupScreen
    movem.l d1-d3/a0-a2/a6,-(sp)
    move.l  _IntuitionBase,a6
    move.l  PubScreenName,a0
    jsr     _LVOLockPubScreen(a6)
    move.l  d0,Scr
    tst.l   d0
    beq     SError
    moveq   #0,d2
    moveq   #0,d3
    jsr     ComputeFont
    move.l  Scr,a0
    move.l  _GadToolsBase,a6
    lea.l   TD,a1
    jsr     _LVOGetVisualInfoA(a6)
    move.l  d0,VisualInfo
    move.l  d0,CL+4
    tst.l   d0
    beq     VError
    jsr     initGet
    move.l  d0,getClass
    tst.l   d0
    beq     CError
    move.l  _IntuitionBase,a6
    move.l  d0,a0
    suba.l  a1,a1
    lea.l   CL,a2
    jsr     _LVONewObjectA(a6)
    move.l  d0,getImage
    tst.l   d0
    beq     OError
    moveq   #0,d0
SDone:
    movem.l (sp)+,d1-d3/a0-a2/a6
    rts
SError:
    moveq   #1,d0
    bra.s   SDone
VError:
    moveq   #2,d0
    bra.s   SDone
CError:
    moveq   #4,d0
    bra.s   SDone
OError:
    moveq   #5,d0
    bra.s   SDone

    XDEF    CloseDownScreen

CloseDownScreen:
    movem.l d0-d1/a0-a1/a6,-(sp)
    move.l  _IntuitionBase,a6
    move.l  getImage,a0
    cmpa.l  #0,a0
    beq.s   NoObj
    jsr     _LVODisposeObject(a6)
NoObj:
    move.l  getClass,a0
    cmpa.l  #0,a0
    beq.s   NoCls
    jsr     _LVOFreeClass(a6)
NoCls:
    move.l  _GadToolsBase,a6
    move.l  VisualInfo,a0
    cmpa.l  #0,a0
    beq.s   NoVis
    jsr     _LVOFreeVisualInfo(a6)
    move.l  #0,VisualInfo
NoVis:
    move.l  _IntuitionBase,a6
    suba.l  a0,a0
    move.l  Scr,a1
    cmpa.l  #0,a1
    beq.s   NoScr
    jsr     _LVOUnlockPubScreen(a6)
    move.l  #0,Scr
NoScr:
    movem.l (sp)+,d0-d1/a0-a1/a6
    rts

    XDEF    CloseSettingsWindow

CloseSettingsWindow:
    movem.l d0-d1/a0-a2/a6,-(sp)
    move.l   _IntuitionBase,a6
    move.l   SettingsMenus,a0
    cmpa.l   #0,a0
    beq      SettingsNMenu
    move.l   SettingsWnd,a0
    jsr      _LVOClearMenuStrip(a6)
    move.l   _GadToolsBase,a6
    move.l   SettingsMenus,a0
    jsr      _LVOFreeMenus(a6)
    move.l   #0,SettingsMenus
SettingsNMenu:
    move.l  _IntuitionBase,a6
    move.l  SettingsWnd,a0
    cmpa.l  #0,a0
    beq     SettingsNWnd
    jsr     _LVOCloseWindow(a6)
    move.l  #0,SettingsWnd
SettingsNWnd:
    move.l  _GadToolsBase,a6
    move.l  SettingsGList,a0
    cmpa.l  #0,a0
    beq     SettingsNGad
    jsr     _LVOFreeGadgets(a6)
    move.l  #0,SettingsGList
SettingsNGad:
    movem.l (sp)+,d0-d1/a0-a2/a6
    rts

    XDEF    OpenEnterSizeWindow

OpenEnterSizeWindow:
    movem.l d1-d4/a0-a4/a6,-(sp)
    move.l  Scr,a0
    moveq   #0,d3
    moveq   #0,d2
    move.w  EnterSizeWidth,d2
    move.w  EnterSizeHeight,d3
    jsr     ComputeFont
    move.l  Scr,a0
    move.l  d2,d0
    jsr     ComputeX
    move.l  d0,d4
    move.w  EnterSizeLeft,d2
    add.w   d2,d0
    add.w   OffX,d0
    move.b  sc_WBorRight(a0),d1
    ext.w   d1
    add.w   d1,d0
    cmp.w   sc_Width(a0),d0
    bls.s   EnterSizeWOk
    move.w  sc_Width(a0),d0
    sub.w   d4,d0
    move.w  d0,d2
EnterSizeWOk:
    move.l  d3,d0
    jsr     ComputeY
    move.l  d0,d4
    move.w  EnterSizeTop,d3
    add.w   d3,d0
    add.w   OffY,d0
    move.b  sc_WBorBottom(a0),d1
    ext.w   d1
    add.w   d1,d0
    cmp.w   sc_Height(a0),d0
    bls.s   EnterSizeHOk
    move.w  sc_Height(a0),d0
    sub.w   d4,d0
    move.w  d0,d3
EnterSizeHOk:
    move.l  _GadToolsBase,a6
    lea.l   EnterSizeGList,a0
    jsr     _LVOCreateContext(a6)
    move.l  d0,a3
    tst.l   d0
    beq     EnterSizeCError
    movem.w d2-d3,-(sp)
    moveq   #0,d3
    lea.l   EnterSizeGTags,a4
EnterSizeGL:
    move.l  _SysBase,a6
    lea.l   EnterSizeNGads,a0
    move.l  d3,d0
    mulu    #gng_SIZEOF,d0
    add.l   d0,a0
    lea.l   BufNewGad,a1
    moveq   #gng_SIZEOF,d0
    jsr     _LVOCopyMem(a6)
    lea.l   BufNewGad,a0
    move.l  VisualInfo,gng_VisualInfo(a0)
    move.l  Font,gng_TextAttr(a0)
    move.w  gng_LeftEdge(a0),d0
    jsr     ComputeX
    add.w   OffX,d0
    move.w  d0,gng_LeftEdge(a0)
    move.w  gng_TopEdge(a0),d0
    jsr     ComputeY
    add.w   OffY,d0
    move.w  d0,gng_TopEdge(a0)
    move.w  gng_Width(a0),d0
    jsr     ComputeX
    move.w  d0,gng_Width(a0)
    move.w  gng_Height(a0),d0
    jsr     ComputeY
    move.w  d0,gng_Height(a0)
    move.l  _GadToolsBase,a6
    lea.l   EnterSizeGTypes,a0
    moveq   #0,d0
    move.l  d3,d1
    asl.l   #1,d1
    add.l   d1,a0
    move.w  (a0),d0
    move.l  a3,a0
    lea.l   BufNewGad,a1
    move.l  a4,a2
    jsr     _LVOCreateGadgetA(a6)
    tst.l   d0
    bne.s    EnterSizeCOK
    movem.w (sp)+,d2-d3
    bra     EnterSizeGError
EnterSizeCOK:
    move.l  d0,a3
    move.l  d3,d0
    asl.l   #2,d0
    lea.l   EnterSizeGadgets,a0
    add.l   d0,a0
    move.l  a3,(a0)
EnterSizeTL:
    tst.l   (a4)
    beq.s   EnterSizeDN
    addq.w  #8,a4
    bra.s   EnterSizeTL
EnterSizeDN:
    addq.w  #4,a4
    addq.w  #1,d3
    cmp.w   #EnterSize_CNT,d3
    bmi     EnterSizeGL
    movem.w (sp)+,d2-d3
    move.l  EnterSizeGList,EnterSizeWG+4
    move.l  Scr,EnterSizeSC+4
    ext.l   d2
    ext.l   d3
    move.l  d2,EnterSizeL+4
    move.l  d3,EnterSizeT+4
    move.l  Scr,a0
    move.w  EnterSizeWidth,d0
    jsr     ComputeX
    add.w   OffX,d0
    move.b  sc_WBorRight(a0),d1
    ext.w   d1
    add.w   d1,d0
    move.l  d0,EnterSizeW+4
    move.w  EnterSizeHeight,d0
    jsr     ComputeY
    add.w   OffY,d0
    move.b  sc_WBorBottom(a0),d1
    ext.w   d1
    add.w   d1,d0
    move.l  d0,EnterSizeH+4
    move.l  _IntuitionBase,a6
    suba.l  a0,a0
    lea.l   EnterSizeWindowTags,a1
    jsr     _LVOOpenWindowTagList(a6)
    move.l  d0,EnterSizeWnd
    tst.l   d0
    beq     EnterSizeWError
    move.l  _GadToolsBase,a6
    move.l  EnterSizeWnd,a0
    suba.l  a1,a1
    jsr     _LVOGT_RefreshWindow(a6)
    moveq   #0,d0
EnterSizeDone:
    movem.l (sp)+,d1-d4/a0-a4/a6
    rts
EnterSizeCError:
    moveq   #1,d0
    bra.s   EnterSizeDone
EnterSizeGError:
    moveq   #2,d0
    bra.s   EnterSizeDone
EnterSizeWError:
    moveq   #4,d0
    bra.s   EnterSizeDone

    XDEF    CloseEnterSizeWindow

CloseEnterSizeWindow:
    movem.l d0-d1/a0-a2/a6,-(sp)
    move.l  _IntuitionBase,a6
    move.l  EnterSizeWnd,a0
    cmpa.l  #0,a0
    beq     EnterSizeNWnd
    jsr     _LVOCloseWindow(a6)
    move.l  #0,EnterSizeWnd
EnterSizeNWnd:
    move.l  _GadToolsBase,a6
    move.l  EnterSizeGList,a0
    cmpa.l  #0,a0
    beq     EnterSizeNGad
    jsr     _LVOFreeGadgets(a6)
    move.l  #0,EnterSizeGList
EnterSizeNGad:
    movem.l (sp)+,d0-d1/a0-a2/a6
    rts

* Page descriptors for the tabbed settings window (MacEmulTabs.asm):
* NGads, GTypes, GTags, Gadgets, ->GList, ->Wnd, ->Width, ->Height, count, next page part
